// This function performs the necessary text transformations.
function transformFilename(inputText) {
    // 1. Identify the filename part.
    // The filename is everything after the last '/' and before the last '.'.
    const parts = inputText.split('/');
    const fullFilename = parts[parts.length - 1]; // e.g., 'Snímek obrazovky 2025-09-19 162321.png'

    // Check if there's a dot to separate the name and extension.
    const lastDotIndex = fullFilename.lastIndexOf('.');
    if (lastDotIndex === -1) {
        // Handle case where there's no extension
        return inputText; 
    }

    // Separate the name and the extension
    let filenameBase = fullFilename.substring(0, lastDotIndex); // 'Snímek obrazovky 2025-09-19 162321'
    const extension = fullFilename.substring(lastDotIndex); // '.png'

    // 2. Transliterate Czech characters and convert to lowercase.
    // Map of common Czech characters to their non-diacritic counterparts.
    const czechMap = {
        'á': 'a', 'č': 'c', 'ď': 'd', 'é': 'e', 'ě': 'e', 'í': 'i', 'ň': 'n', 
        'ó': 'o', 'ř': 'r', 'š': 's', 'ť': 't', 'ú': 'u', 'ů': 'u', 'ý': 'y', 
        'ž': 'z',
        'Á': 'a', 'Č': 'c', 'Ď': 'd', 'É': 'e', 'Ě': 'e', 'Í': 'i', 'Ň': 'n', 
        'Ó': 'o', 'Ř': 'r', 'Š': 's', 'Ť': 't', 'Ú': 'u', 'Ů': 'u', 'Ý': 'y', 
        'Ž': 'z'
    };

    // Replace characters using the map
    let transformedName = filenameBase.split('').map(char => czechMap[char] || char).join('');

    // Ensure all characters are lowercase, which should be mostly done by the map, 
    // but this catches any non-mapped uppercase Latin letters.
    transformedName = transformedName.toLowerCase();

    // 3. Replace whitespaces and hyphens with underscores.
    // This uses a regular expression to replace one or more occurrences of 
    // whitespace (\s) or a hyphen (-) with a single underscore (_).
    transformedName = transformedName.replace(/[\s-]/g, '_'); 

    // 4. Reconstruct the full path.
    // Rejoin the path components, replacing the original full filename with the new one.
    parts[parts.length - 1] = transformedName + extension;

    return parts.join('/'); 
}

// ----------------------------------------------------------------------
// 1. TAILORED INPUT: Retrieve the path from the 'filePath' field
const inputText = $input.first().json.filePath; 
// ----------------------------------------------------------------------

// Run the transformation.
const outputText = transformFilename(inputText);

// Set the output for the Code node.
// It creates a new field named 'modifiedPath' with the transformed string.
return [{
    json: {
        modifiedPath: outputText
    }
}];
